import{_ as t,o as a,c as i,ah as r}from"./chunks/framework.BsNNkeaH.js";const h=JSON.parse('{"title":"Activités extrascolaires","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/activites-extrascolaires.md","filePath":"src/guide/admin/activites-extrascolaires.md"}'),s={name:"guide/admin/activites-extrascolaires.md"};function n(l,e,c,o,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="activites-extrascolaires" tabindex="-1">Activités extrascolaires <a class="header-anchor" href="#activites-extrascolaires" aria-label="Permalink to &quot;Activités extrascolaires&quot;">​</a></h1><p>Cette section couvre la mise en place du catalogue d&#39;activités périscolaires (piscine, théâtre, etc.) et la planification de leurs séances. Le suivi de présence à ces séances est ensuite du ressort de la vie scolaire, pas de l&#39;administration.</p><h2 id="creer-une-activite" tabindex="-1">Créer une activité <a class="header-anchor" href="#creer-une-activite" aria-label="Permalink to &quot;Créer une activité&quot;">​</a></h2><p><strong>Paramétrage scolaire → Activités périscolaires</strong> liste le catalogue d&#39;activités de l&#39;établissement.</p><p>Pour créer une activité :</p><ol><li>Cliquez sur <strong>Nouvelle activité</strong>.</li><li>Renseignez le <strong>Nom</strong> et, facultativement, une <strong>Description</strong>.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><h2 id="planifier-une-seance" tabindex="-1">Planifier une séance <a class="header-anchor" href="#planifier-une-seance" aria-label="Permalink to &quot;Planifier une séance&quot;">​</a></h2><p><strong>Paramétrage scolaire → Séances périscolaires</strong> planifie des créneaux récurrents pour une activité, par site et niveau, avec un encadrant désigné.</p><p>Pour créer une séance :</p><ol><li>Cliquez sur <strong>Nouvelle séance</strong>.</li><li>Renseignez les champs de la section « Activité » ci-dessous.</li><li>Renseignez les champs de la section « Horaire » ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Section « Activité » :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Activité</td><td>choisie dans le catalogue</td></tr><tr><td>Site</td><td>—</td></tr><tr><td>Département</td><td>niveau concerné par la séance</td></tr><tr><td>Encadrant</td><td>membre du personnel responsable de la séance</td></tr></tbody></table><p>Section « Horaire » :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Jour de la semaine</td><td>—</td></tr><tr><td>Heure de début</td><td>—</td></tr><tr><td>Heure de fin</td><td>—</td></tr></tbody></table><p>Chaque séance est ensuite modifiable ou supprimable individuellement depuis la liste des séances.</p>',15)])])}const v=t(s,[["render",n]]);export{h as __pageData,v as default};
